1	package agentusageview
2	
3	import (
4		"strings"
5		"testing"
6		"unicode/utf8"
7	
8		"github.com/anthnel/devdesk/internal/agentusage"
9		"github.com/anthnel/devdesk/internal/ui/testutil"
10	)
11	
12	// Live updates, step 1 (DEVDESK-45): rebuilding the agent rows while keeping
13	// the cursor on the same agent, the filter and the sort, and remeasuring only
14	// when the table holds a different population.
15	
16	// selectAgent moves the cursor onto the visible row with the given ID ("" is
17	// the orchestrator).
18	func selectAgent(t *testing.T, m Model, id string) Model {
19		t.Helper()
20		for i, r := range m.agentTable.Visible() {
21			if r.ID == id {
22				m.agentTable.SetCursor(i)
23				return m
24			}
25		}
26		t.Fatalf("no visible agent %q in %q", id, visibleIDs(m))
27		return m
28	}
29	
30	func selectedID(t *testing.T, m Model) string {
31		t.Helper()
32		r, ok := m.agentTable.Selected()
33		if !ok {
34			t.Fatal("no agent selected")
35		}
36		return r.ID
37	}
38	
39	func agentColumnWidth(m Model) int { return m.agentTable.Table().Columns()[0].Width }
40	
41	func TestAgentKeysIdentifyRowsAcrossRebuilds(t *testing.T) {
42		tests := []struct {
43			name   string
44			agents []agentusage.Agent
45			want   []string
46		}{
47			{"orchestrator alone", []agentusage.Agent{orchestrator(1, 0)}, []string{"main"}},
48			{
49				"tree order",
50				[]agentusage.Agent{orchestrator(1, 0), subAgent("a01", "coder", 1, 0), subAgent("a02", "tester", 1, 0)},
51				[]string{"main", "sub:a01#0", "sub:a02#0"},
52			},
53			{
54				"two sub-agents sharing one ID stay distinct",
55				[]agentusage.Agent{subAgent("dup", "coder", 1, 0), subAgent("dup", "tester", 1, 0)},
56				[]string{"sub:dup#0", "sub:dup#1"},
57			},
58		}
59		for _, tt := range tests {
60			t.Run(tt.name, func(t *testing.T) {
61				got := agentKeys(agentRows(agentusage.Usage{Agents: tt.agents}, true))
62				if strings.Join(got, "|") != strings.Join(tt.want, "|") {
63					t.Errorf("agentKeys = %q, want %q", got, tt.want)
64				}
65			})
66		}
67	}
68	
69	func TestACursorStaysOnItsAgentWhenAnotherSortsBeforeIt(t *testing.T) {
70		base := agentusage.Usage{Agents: []agentusage.Agent{
71			orchestrator(10, 0), subAgent("a01", "coder", 10, 0), subAgent("a02", "tester", 10, 0),
72		}}
73		m := selectAgent(t, atWideAgents(t, base), "a02")
74		if m.agentTable.Cursor() != 2 {
75			t.Fatalf("setup: cursor = %d, want 2", m.agentTable.Cursor())
76		}
77	
78		grown := agentusage.Usage{Agents: append([]agentusage.Agent{subAgent("a00", "planner", 10, 0)}, base.Agents...)}
79		m = m.withUsage(grown, false)
80	
81		if got := selectedID(t, m); got != "a02" {
82			t.Errorf("selected %q after a00 joined, want a02", got)
83		}
84		if got := m.agentTable.Cursor(); got != 3 {
85			t.Errorf("cursor = %d, want 3 (main, a00, a01, a02)", got)
86		}
87	}
88	
89	func TestACursorFollowsItsAgentWhenTheTotalSortReordersRows(t *testing.T) {
90		small := agentusage.Usage{Agents: []agentusage.Agent{
91			totalled(orchestrator(0, 0), 1000, 0),
92			totalled(subAgent("a01", "coder", 0, 0), 800, 0),
93			totalled(subAgent("a02", "tester", 0, 0), 300, 0),
94		}}
95		m := atWideAgents(t, small)
96		m, _ = opened(t, m, ".") // Total, largest first
97		if got := visibleIDs(m); got != ",a01,a02" {
98			t.Fatalf("setup: sorted order = %q", got)
99		}
100		m = selectAgent(t, m, "a01")
101		if m.agentTable.Cursor() != 1 {
102			t.Fatalf("setup: cursor = %d, want 1", m.agentTable.Cursor())
103		}
104	
105		grown := agentusage.Usage{Agents: []agentusage.Agent{
106			small.Agents[0],
107			totalled(subAgent("a01", "coder", 0, 0), 2000, 0),
108			small.Agents[2],
109		}}
110		m = m.withUsage(grown, false)
111	
112		if got := visibleIDs(m); got != "a01,,a02" {
113			t.Fatalf("order after growth = %q, want a01,,a02", got)
114		}
115		if got := selectedID(t, m); got != "a01" {
116			t.Errorf("selected %q, want the coder still", got)
117		}
118		if got := m.agentTable.Cursor(); got != 0 {
119			t.Errorf("cursor = %d, want 0", got)
120		}
121	}
122	
123	func TestAVanishedAgentClampsTheCursorWithoutPanicking(t *testing.T) {
124		m := selectAgent(t, atWideAgents(t, threeSubs()), "a03")
125	
126		m = m.withUsage(agentusage.Usage{Agents: threeSubs().Agents[:2]}, true)
127	
128		if n := len(m.agentTable.Visible()); n != 2 {
129			t.Fatalf("%d rows, want 2", n)
130		}
131		if _, ok := m.agentTable.Selected(); !ok {
132			t.Error("a row must stay selected")
133		}
134		if c := m.agentTable.Cursor(); c < 0 || c > 1 {
135			t.Errorf("cursor = %d out of range", c)
136		}
137	}
138	
139	func TestTheFilterAndItsBarSurviveAnUpdate(t *testing.T) {
140		m := atWideAgents(t, threeSubs())
141		m = send(t, m, testutil.Key("/"))
142		for _, k := range testutil.Type("test") {
143			m = feed(t, m, k)
144		}
145		m = send(t, m, testutil.Key("enter"))
146		if got := visibleIDs(m); got != "a02" {
147			t.Fatalf("setup: filter shows %q", got)
148		}
149	
150		grown := threeSubs()
151		grown.Agents[2] = subAgent("a02", "tester", 999, 0)
152		m = m.withUsage(grown, false)
153	
154		if got := visibleIDs(m); got != "a02" {
155			t.Errorf("visible = %q, want only the tester", got)
156		}
157		if q := m.agentTable.FilterBar().SearchQuery(); q != "test" {
158			t.Errorf("query = %q, want test", q)
159		}
160		if !m.FilterBarVisible() {
161			t.Error("the filter bar must stay visible")
162		}
163	}
164	
165	func TestWithUsageClearsTheLoadingAndErrorStates(t *testing.T) {
166		m := atWideAgents(t, threeSubs())
167		m.agentsLoading, m.agentsErr = true, true
168	
169		m = m.withUsage(threeSubs(), false)
170	
171		if m.agentsLoading || m.agentsErr {
172			t.Errorf("agentsLoading=%v agentsErr=%v, want both false", m.agentsLoading, m.agentsErr)
173		}
174	}
175	
176	func TestRemeasureHappensOnlyOnAFullReadOrAChangedPopulation(t *testing.T) {
177		long := strings.Repeat("x", 30)
178		coderOnly := func(typ string, models ...string) agentusage.Usage {
179			c := subAgent("a01", typ, 1, 0)
180			if models != nil {
181				c.Models = models
182			}
183			return agentusage.Usage{Agents: []agentusage.Agent{orchestrator(1, 0), c}}
184		}
185		tests := []struct {
186			name      string
187			next      agentusage.Usage
188			remeasure bool
189			widened   bool
190		}{
191			{"same population, longer type, partial delta", coderOnly(long), false, false},
192			{"same population, full read", coderOnly(long), true, true},
193			{"a new sub-agent", agentusage.Usage{Agents: []agentusage.Agent{
194				orchestrator(1, 0), subAgent("a01", "coder", 1, 0), subAgent("a02", long, 1, 0),
195			}}, false, true},
196			{"a model added to an existing agent", coderOnly(long, "m-b", "m-c"), false, true},
197		}
198		for _, tt := range tests {
199			t.Run(tt.name, func(t *testing.T) {
200				m := atWideAgents(t, coderOnly("coder"))
201				before := agentColumnWidth(m)
202	
203				m = m.withUsage(tt.next, tt.remeasure)
204	
205				got := agentColumnWidth(m)
206				if tt.widened && got < utf8.RuneCountInString(lastStem+long) {
207					t.Errorf("Agent column is %d wide, want at least %d", got, len(lastStem+long))
208				}
209				if !tt.widened && got != before {
210					t.Errorf("Agent column went from %d to %d, want unchanged", before, got)
211				}
212			})
213		}
214	}
215	
216	func TestANewSubAgentIsRenderedWholeAtOnce(t *testing.T) {
217		m := atWideAgents(t, agentusage.Usage{Agents: []agentusage.Agent{
218			orchestrator(1, 0), subAgent("a01", "coder", 1, 0),
219		}})
220	
221		m = m.withUsage(agentusage.Usage{Agents: []agentusage.Agent{
222			orchestrator(1, 0), subAgent("a01", "coder", 1, 0), subAgent("a02", "general-purpose", 1, 0),
223		}}, false)
224	
225		if view := stripANSI(m.View()); !strings.Contains(view, lastStem+"general-purpose") {
226			t.Errorf("the new agent's type is cut:\n%s", view)
227		}
228	}
